helper=f('recipeProject','Create one actual recipe definition and display consumer with stable identities and common headers.','static HmiProject recipeProject()', '''    HmiProject project;
    HmiConfigurationNode node;
    RecipeProperties properties;
    HmiObject object;
    project.languages = {QStringLiteral("中文"),QStringLiteral("English"),QStringLiteral("Deutsch")}; node.id = QStringLiteral("recipe-definition-1"); node.name = QStringLiteral("C31"); node.kind = QStringLiteral("recipe"); node.active = true; node.implemented = true; node.properties = properties.toJson(); project.configurationNodes = {node}; object.id = QStringLiteral("recipe-display-1"); object.name = QStringLiteral("配方显示器"); object.type = QStringLiteral("recipe"); object.geometry = QRect(40,100,620,250); object.recipeDisplay.recipeId = node.id; project.objects = {object}; return project;''',returns='Complete independent C31 editor project.')
s=s.replace('QTEST_MAIN(Stage4ControlTests)',helper+''.join(f('Stage4ControlTests::'+name,desc,'void Stage4ControlTests::'+name+'()',body) for name,desc,body in methods)+'QTEST_MAIN(Stage4ControlTests)');p.write_text(s,encoding='utf-8',newline='\n')
